-- Miro — Дошки та діаграми
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'miro.com' OR LOWER(`name`) = LOWER('Miro'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Miro', NULL, 'https://miro.com', NULL, NULL, 'Онлайн-дошка для командної роботи з AI: брейнштормінг, діаграми, планування, воркшопи та AI-функції, що підсумовують і структурують ідеї.', 'An online whiteboard for team collaboration with AI: brainstorming, diagrams, planning, workshops and AI features that summarise and structure ideas.', 'Miro — візуальний робочий простір, де команди разом проводять брейнштормінги, малюють діаграми й схеми процесів, планують проєкти та воркшопи. AI допомагає генерувати ідеї, групувати стікери, підсумовувати дошку та створювати діаграми з тексту; є понад 250 інтеграцій і MCP-доступ для AI-агентів. Тарифи за учасника на місяць при річній оплаті: Free — 3 дошки й пробні AI-кредити; Starter — $8 (необмежені дошки, 25 AI-кредитів); Business — $20 (50 AI-кредитів); Enterprise — від 30 учасників, за запитом. Помісячна оплата на 20% дорожча.', 'Miro is a visual workspace where teams brainstorm, draw diagrams and process maps, plan projects and run workshops together. AI helps generate ideas, cluster sticky notes, summarise boards and create diagrams from text; there are 250+ integrations and MCP access for AI agents. Plans per member a month billed annually: Free — 3 boards and trial AI credits; Starter — $8 (unlimited boards, 25 AI credits); Business — $20 (50 AI credits); Enterprise — 30+ members, on request. Monthly billing costs 20% more.', 'Безмежна дошка для командної роботи
AI-ідеї, групування й підсумки
Діаграми з тексту
250+ інтеграцій і MCP', 'Infinite canvas for teamwork
AI ideas, clustering and summaries
Diagrams from text
250+ integrations and MCP', 'Продуктові, дизайнерські та agile-команди, фасилітатори воркшопів.', 'Product, design and agile teams and workshop facilitators.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
