SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'meetjamie.ai' OR LOWER(`name`) = LOWER('Jamie'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Jamie', NULL, 'https://www.meetjamie.ai', NULL, NULL, 'AI-нотатки для онлайн- і офлайн-зустрічей без бота: розпізнавання спікерів, задачі й транскрипція 99+ мовами; європейський сервіс з цінами в євро.', 'Bot-free AI meeting notes for online and in-person meetings: speaker recognition, task detection and transcription in 99+ languages; a European service priced in euros.', 'Jamie робить нотатки зустрічей без бота, який підключається до дзвінка, і працює як для онлайн-, так і для живих зустрічей. Він розпізнає спікерів, виділяє задачі, транскрибує понад 99 мовами та зберігає записи; старші тарифи додають інтеграції з Salesforce, HubSpot, Asana й API. Ціни в євро при річній оплаті: Free — 10 нотаток на місяць (до 30 хв); Plus — €21 на місяць; Pro — €39 (необмежені нотатки до 5 годин); Team — €33 за користувача; Enterprise — за запитом, з SAML SSO.', 'Jamie takes meeting notes without a bot joining the call and works for both online and in-person meetings. It recognises speakers, detects tasks, transcribes in 99+ languages and stores records; higher plans add Salesforce, HubSpot and Asana integrations and an API. Prices in euros billed annually: Free — 10 notes a month (up to 30 min); Plus — €21 a month; Pro — €39 (unlimited notes up to 5 hours); Team — €33 per user; Enterprise on request, with SAML SSO.', 'Нотатки без бота в дзвінку
Онлайн- і живі зустрічі
Розпізнавання спікерів і задач
99+ мов', 'Notes with no bot in the call
