INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Smartcat', NULL, 'https://www.smartcat.com', NULL, NULL, 'AI-платформа перекладу й локалізації: AI-«колеги» перекладають, створюють і перевіряють контент 280+ мовами, з пам''яттю перекладів і маркетплейсом редакторів.', 'An AI translation and localisation platform: AI ''coworkers'' translate, create and review content in 280+ languages, with translation memory and a marketplace of editors.', 'Smartcat допомагає компаніям перекладати й локалізувати контент у масштабі. AI-«колеги» відповідають за переклад, створення контенту, рецензування, оновлення та контроль якості, а за потреби підключаються професійні редактори з маркетплейсу. Підтримується понад 280 мов і інтеграції з Google Drive, Figma, GitHub, Jira та CMS; повтори й збіги з пам''яттю перекладів не тарифікуються. Тарифи на рік: Adapt — $1 200 (100 тис. Smartwords); Accelerate — $24 000 (1 млн); Anticipate — $60 000 (2 млн, API, SSO); Autonomous — за запитом. Користувачі необмежені.', 'Smartcat helps companies translate and localise content at scale. AI ''coworkers'' handle translation, content creation, review, updates and quality checks, and professional editors from the marketplace can step in when needed. It supports 280+ languages and integrates with Google Drive, Figma, GitHub, Jira and CMS platforms; repetitions and translation memory matches are free. Annual plans: Adapt — $1,200 (100K Smartwords); Accelerate — $24,000 (1M); Anticipate — $60,000 (2M, API, SSO); Autonomous on request. Users are unlimited.', 'AI-переклад 280+ мовами
Пам''ять перекладів без доплат
Маркетплейс професійних редакторів
Інтеграції з Figma, GitHub, CMS', 'AI translation in 280+ languages
Free translation memory matches
Marketplace of professional editors
Figma, GitHub and CMS integrations', 'Компанії, що локалізують продукти й маркетинг.', 'Companies localising products and marketing.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'smartcat.com' OR LOWER(`name`) = LOWER('Smartcat')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'translation-languages' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'translation-languages' AND s.`slug` = 'translation' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'An AI translation and localisation platform: AI ''coworkers'' translate, create and review content in 280+ languages, with translation memory and a marketplace of editors.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Smartcat helps companies translate and localise content at scale. AI ''coworkers'' handle translation, content creation, review, updates and quality checks, and professional editors from the marketplace can step in when needed. It supports 280+ languages and integrates with Google Drive, Figma, GitHub, Jira and CMS platforms; repetitions and translation memory matches are free. Annual plans: Adapt — $1,200 (100K Smartwords); Accelerate — $24,000 (1M); Anticipate — $60,000 (2M, API, SSO); Autonomous on request. Users are unlimited.', 'manual' FROM DUAL WHERE @new = 1;
